package com.vandorlabs.neoforge;

import com.vandorlabs.neoforge.credentials.*;
import com.vandorlabs.persistence.ControlMountSettings;
import net.minecraft.core.*;
import net.minecraft.core.component.DataComponents;
import net.minecraft.nbt.*;
import net.minecraft.network.chat.Component;
import net.minecraft.server.level.*;
import net.minecraft.world.*;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.phys.*;

/** Adjacent Screens consume cached bounded display metadata, never physical inventory on a draw. */
final class StandaloneReaderChipViewChecks {
    private static int checks;
    private static volatile Object blackhole;
    private static void need(boolean value,String why){checks++;if(!value)throw new AssertionError("Reader chip view: "+why);}
    static void run(ServerLevel level,NativeCredentialReaderBlock card,NativeCredentialReaderBlock chip)throws Exception {
        var cardOwner=(NativeCredentialReaderEntity)card.newBlockEntity(BlockPos.ZERO,card.defaultBlockState());need(cardOwner.chipView()==null,"card reader exposes no chip display");
        BlockPos pos=new BlockPos(5200,90,5150);level.setChunkForced(pos.getX()>>4,pos.getZ()>>4,true);level.getChunkAt(pos);level.setBlock(pos.south(),Blocks.STONE.defaultBlockState(),3);level.setBlock(pos,chip.defaultBlockState(),3);var owner=(NativeCredentialReaderEntity)level.getBlockEntity(pos);need(owner.chipView()!=null&&!owner.chipView().reader.occupied()&&owner.chipView().journal==null,"empty chip reader has bounded empty projection");
        var player=net.neoforged.neoforge.common.util.FakePlayerFactory.getMinecraft(level);player.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);player.setShiftKeyDown(false);player.getInventory().clearContent();player.setPos(pos.getX()+.5,pos.getY(),pos.getZ()-1);
        var raw=new CompoundTag();raw.putString("id","vandorlabs:data_chip");raw.putByte("Count",(byte)3);raw.putShort("Damage",(short)2);raw.putString("FutureRoot","PRIVATE_OWNERSHIP");var caps=new CompoundTag();caps.putString("missing:cap","PRIVATE_CAPABILITY");raw.put("ForgeCaps",caps);var data=new CompoundTag();data.putString("ChipType","journal");data.putString("JournalTitle","Bounded journal");var entries=new ListTag();entries.add(StringTag.valueOf("Long shared text "+"a".repeat(600)));entries.add(StringTag.valueOf("Second page"));data.put("JournalPages",entries);data.putString("FuturePayload","PRIVATE_PAYLOAD");raw.put("tag",data);
        var held=NativeCredentialItems.readStack(raw,level.registryAccess());held.set(DataComponents.CUSTOM_NAME,Component.literal("Public journal name"));player.setItemInHand(InteractionHand.MAIN_HAND,held);need(player.gameMode.useItemOn(player,level,held,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(pos),Direction.NORTH,pos,false)).consumesAction()&&held.getCount()==2,"actual journal insertion transfers one physical owner");
        var view=owner.chipView();need(view!=null&&view.reader.occupied()&&view.journal!=null&&view.journal.pages.size()>1&&!view.master&&"Public journal name".equals(view.displayName),"prepared journal and custom name exposed");need(view==owner.visual().chipView()&&view.reader==owner.visual().contents()&&view.motion==owner.visual().motion(),"one coherent immutable visual carries chip projection");
        var layout=view.journal;var dto=owner.getUpdateTag(level.registryAccess());need(owner.chipView().journal==layout,"packet publication does not repaginate physical item");String text=dto.toString();need(!text.contains("PRIVATE_")&&!text.contains("ForgeCaps")&&!text.contains("InsertedToken")&&!text.contains("TokenReturnTo"),"only bounded display data enters DTO");var bytes=new java.io.ByteArrayOutputStream();try(var output=new java.io.DataOutputStream(bytes)){NbtIo.write(dto,output);}need(bytes.size()<=16384,"complete reader DTO stays within16KiB");
        var client=new NativeCredentialReaderEntity(owner.getType(),pos,owner.getBlockState(),true);client.loadWithComponents(dto,level.registryAccess());need(client.chipView()!=null&&client.chipView().write().equals(dto.getCompound("ReaderChipView")),"public chunk projection round trip");var originalClient=client.chipView();var bad=dto.copy();bad.getCompound("ReaderChipView").put("InsertedToken",raw.copy());client.loadWithComponents(bad,level.registryAccess());need(client.chipView()==originalClient,"malformed private field cannot replace coherent public view");client.loadWithComponents(dto,level.registryAccess());client.setLevel(level);need(client.inert()&&client.chipView()==null&&client.outputLevel()==0&&client.saveWithoutMetadata(level.registryAccess()).equals(dto),"public DTO is never a server inventory snapshot");
        need(owner.configure(player,false,2,0,ControlMountSettings.of(1,2,3))&&owner.chipView().journal==layout,"policy publication reuses prepared text");var modelData=owner.getModelData();var mounted=modelData.get(NativeBinaryControlBlockEntity.VISUAL);need(mounted.mount().height==1&&mounted.mount().tilt==2&&mounted.mount().direction==3&&mounted.rotation()==owner.visual().rotation(),"prepared terrain model data matches coherent mounted projection");player.setItemInHand(InteractionHand.MAIN_HAND,NativeCredentialItems.dataChip(3));need(owner.interact(player,InteractionHand.MAIN_HAND)&&owner.chipView().journal==layout&&owner.visual().motion().rejectedFor()>0,"rejection overlay does not reconstruct journal");need(owner.getModelData()==modelData,"contents/pulse/rejection changes reuse immutable terrain model data");
        var warm=owner.chipView();var bean=(com.sun.management.ThreadMXBean)java.lang.management.ManagementFactory.getThreadMXBean();long thread=Thread.currentThread().threadId();for(int batch=0;batch<8;batch++){bean.getThreadAllocatedBytes(thread);reads(owner,20000);}long allocated=0;for(int batch=0;batch<3;batch++){long before=bean.getThreadAllocatedBytes(thread);reads(owner,10000);allocated=bean.getThreadAllocatedBytes(thread)-before;need(blackhole==warm&&allocated==0,"10000 warm display reads allocate0B, batch="+batch+" actual="+allocated);}
        var removed=owner.takeForDrop();need(removed.getCount()==1&&NativeCredentialItems.legacyCredentialData(removed).getString("FutureRoot").equals("PRIVATE_OWNERSHIP")&&NativeCredentialItems.legacyCredentialData(removed).getCompound("ForgeCaps").equals(caps),"private imported ownership unchanged after preparing display");need(owner.chipView()!=null&&!owner.chipView().reader.occupied()&&owner.chipView().journal==null,"removal invalidates cached display");
        int maximum=maximum(level,chip);level.removeBlock(pos,false);player.getInventory().clearContent();System.out.println("Native standalone reader chip projection PASS checks="+checks+" DTOBytes="+bytes.size()+" maxDTOBytes="+maximum+" warm10000=0B immutable prepared text shared");
    }
    private static void reads(NativeCredentialReaderEntity owner,int count){for(int i=0;i<count;i++)blackhole=owner.chipView();}
    private static int maximum(ServerLevel level,NativeCredentialReaderBlock block)throws Exception {
        var token=NativeCredentialItems.dataChip(2);var data=new CompoundTag();data.putString("ChipType","journal");data.putString("JournalTitle","界".repeat(1000));var pages=new ListTag();for(int i=0;i<20;i++)pages.add(StringTag.valueOf("界".repeat(1000)));data.put("JournalPages",pages);data.putString("Future","PRIVATE_MAXIMUM");token.set(DataComponents.CUSTOM_DATA,net.minecraft.world.item.component.CustomData.of(data));token.set(DataComponents.CUSTOM_NAME,Component.literal("界".repeat(1000)));var raw=new CompoundTag();raw.put("InsertedToken",NativeCredentialItems.writeStack(token,level.registryAccess()));var owner=(NativeCredentialReaderEntity)block.newBlockEntity(BlockPos.ZERO,block.defaultBlockState());owner.loadWithComponents(raw,level.registryAccess());var dto=owner.getUpdateTag(level.registryAccess());var bytes=new java.io.ByteArrayOutputStream();try(var output=new java.io.DataOutputStream(bytes)){NbtIo.write(dto,output);}need(bytes.size()<=16384&&!dto.toString().contains("PRIVATE_MAXIMUM")&&owner.chipView().displayName.length()==256,"maximum multibyte journal/name is bounded before publication");var client=(NativeCredentialReaderEntity)block.newBlockEntity(BlockPos.ZERO,block.defaultBlockState());client.loadWithComponents(dto,level.registryAccess());need(client.chipView()!=null&&client.chipView().write().equals(dto.getCompound("ReaderChipView")),"maximum public journal round trip");
        var master=new CompoundTag();master.put("InsertedToken",NativeCredentialItems.writeStack(NativeCredentialItems.dataChip(3),level.registryAccess()));owner.loadWithComponents(master,level.registryAccess());need(owner.chipView().master&&owner.chipView().journal==null,"nonjournal company chip exposes only master display state");var unknown=new CompoundTag();unknown.putString("InsertedToken","future physical owner");owner.loadWithComponents(unknown,level.registryAccess());need(owner.inert()&&owner.chipView()==null&&!owner.getUpdateTag(level.registryAccess()).contains("ReaderChipView"),"opaque failed ownership publishes no chip metadata");return bytes.size();
    }
}
